package com.hospital.platform.iam.interfaces;
import java.util.List; import java.util.Map; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AdminQueryService { private final JdbcTemplate jdbc; public AdminQueryService(JdbcTemplate jdbc){this.jdbc=jdbc;} public List<Map<String,Object>> roles(){return jdbc.queryForList("select id,role_code,role_name,data_scope,status from sys_role where deleted=0 order by id");} public List<Map<String,Object>> permissions(){return jdbc.queryForList("select id,permission_code,permission_name,permission_type from sys_permission where deleted=0 order by id");} public List<Long> rolePermissionIds(long roleId){return jdbc.queryForList("select permission_id from sys_role_permission where role_id=? order by permission_id",Long.class,roleId);} public List<Map<String,Object>> menus(){return jdbc.queryForList("select id,menu_code,menu_name,route_path,component from sys_menu where deleted=0 order by sort_order");} public List<Map<String,Object>> organizations(){return jdbc.queryForList("select id,org_code,org_name,org_type,parent_id from sys_organization where deleted=0 order by id");}
 public void createRole(String code,String name,String dataScope){jdbc.update("insert into sys_role(role_code,role_name,data_scope) values(?,?,?)",code,name,dataScope);}
 @Transactional public void replaceRolePermissions(long roleId,List<Long> ids){Integer exists=jdbc.queryForObject("select count(*) from sys_role where id=? and deleted=0",Integer.class,roleId);if(exists==null||exists==0)throw new IllegalArgumentException("role not found");jdbc.update("delete from sys_role_permission where role_id=?",roleId);if(ids!=null)for(Long id:ids)jdbc.update("insert into sys_role_permission(role_id,permission_id) select ?,id from sys_permission where id=? and status=1 and deleted=0",roleId,id);}}
